// Loads the pregenerated scientificName → Wikidata entity URI map shipped
// at /birdnet/wikidata.json. Generated by scripts/generate-wikidata-map.ts
// using the same resolution chain as the runtime fallback in
// src/lib/birdnet/wikidata.ts, so a hit here is byte-identical to what a
// live lookup would have returned.
//
// The map is best-effort: a missing file, a malformed payload, or a
// missing species all degrade silently to an empty map. Callers
// (currently useAutoPublishDetection) are expected to fall through to
// the live network chain when this returns null, so an out-of-date
// or absent map never breaks publishing — it just removes the
// fast-path optimization.

interface WikidataMapFile {
  /** ISO-8601 timestamp of when the map was generated. */
  generatedAt: string;
  /** Source labels file path the map was derived from. */
  source: string;
  /**
   * Map from scientific name (exactly as it appears in labels.txt,
   * before the `_` separator) to the canonical Wikidata entity URI
   * `https://www.wikidata.org/entity/Q<id>`. Species we couldn't
   * resolve at build time are omitted entirely so a missing key is
   * indistinguishable from "never tried" — both fall through to live
   * lookup at runtime.
   */
  entries: Record<string, string>;
}

let mapPromise: Promise<Map<string, string>> | null = null;

/**
 * Fetch and parse `/birdnet/wikidata.json` once per page load. Subsequent
 * calls return the same in-memory `Map`. Network or parse failures
 * resolve to an empty map rather than rejecting, so the runtime fallback
 * chain stays in charge of error semantics.
 */
function loadWikidataMap(): Promise<Map<string, string>> {
  if (!mapPromise) {
    mapPromise = (async () => {
      let res: Response;
      try {
        res = await fetch('/birdnet/wikidata.json', {
          headers: { accept: 'application/json' },
        });
      } catch {
        return new Map();
      }
      if (!res.ok) return new Map();
      let data: unknown;
      try {
        data = await res.json();
      } catch {
        return new Map();
      }
      // Defensive validation: a corrupted or wrong-shape payload
      // shouldn't poison the runtime — silently fall back to empty.
      const entries = (data as Partial<WikidataMapFile>)?.entries;
      if (!entries || typeof entries !== 'object') return new Map();
      const map = new Map<string, string>();
      for (const [scientificName, entityUri] of Object.entries(entries)) {
        if (
          typeof entityUri === 'string' &&
          /^https:\/\/www\.wikidata\.org\/entity\/Q\d+$/.test(entityUri)
        ) {
          map.set(scientificName, entityUri);
        }
      }
      return map;
    })();
  }
  return mapPromise;
}

/**
 * Resolve a species' Wikidata entity URI from the pregenerated map, or
 * null if the species isn't present. The lookup is keyed on scientific
 * name only — that's the canonical, stable identifier for a BirdNET
 * label, and the live fallback chain is responsible for the
 * common-name-only edge cases the build-time generator already tried.
 */
export async function lookupPregeneratedEntityUri(
  scientificName: string,
): Promise<string | null> {
  if (!scientificName) return null;
  const map = await loadWikidataMap();
  return map.get(scientificName) ?? null;
}
